            parts = list(map(int, lines[2 + i].split()))
            edges.append((parts[0], parts[1], parts[2]))

    if m == 0:
        return '0'

    class Dinic:
        def __init__(self, sink):
            self.graph = [[] for _ in range(sink)]
            self.level = []

        def add_edge(self, u, v, cap):
            self.graph[u].append([v, len(self.graph[v]), cap])
            self.graph[v].append([u, len(self.graph[u]) - 1, 0])

        def bfs(self, s, t):
            self.level = [-1] * len(self.graph)
            self.level[s] = 0
            q = deque([s])
            while q:
                u = q.popleft()
                for v, _, cap in self.graph[u]:
                    if cap > 0 and self.level[v] < 0:
                        self.level[v] = self.level[u] + 1
                        q.append(v)
            return self.level[t] >= 0

        def dfs(self, u, t, f, ptr):
            if f == 0 or u == t:
                return f
            for i in range(ptr[u], len(self.graph[u])):
                ptr[u] = i
                v, rev, cap = self.graph[u][i]
                if cap > 0 and self.level[v] == self.level[u] + 1:
                    pushed = self.dfs(v, t, min(f, cap), ptr)
                    if pushed > 0:
                        self.graph[u][i][2] -= pushed
                        self.graph[v][rev][2] += pushed
                        return pushed
            return 0

        def max_flow(self, s, t):
            total = 0
            while self.bfs(s, t):
                ptr = [0] * len(self.graph)
                while True:
                    pushed = self.dfs(s, t, float('inf'), ptr)
                    if pushed == 0:
                        break
                    total += pushed
            return total

    source = 0
    sink = n + m + 1
    dinic = Dinic(sink + 1)
    total_edge_weight = 0

    for i, (v, u, w) in enumerate(edges):
