    indegree = [0] * (n + 1)
    for u in range(1, n + 1):
        for v in adj[u]:
            indegree[v] += 1

    queue = deque([i for i in range(1, n + 1) if indegree[i] == 0])
    topo_count = 0
    while queue:
        u = queue.popleft()
        topo_count += 1
        for v in adj[u]:
            indegree[v] -= 1
            if indegree[v] == 0:
                queue.append(v)

    if topo_count < n:
        # Has cycles - find longest cycle
        visited = [False] * (n + 1)
        def get_longest_cycle_from(start):
            stack = [(start, 0)]  # node, path_length
            visited[start] = True
            path = [start]
            max_len = 1
            while stack:
                node, _ = stack.pop()
                for neighbor in adj[node]:
                    if neighbor in path:
                        idx = path.index(neighbor)
                        max_len = max(max_len, len(path) - idx)
                    elif not visited[neighbor]:
                        visited[neighbor] = True
                        path.append(neighbor)
                        stack.append((neighbor, len(path)))
            return max_len

        max_cycle = 1
        for i in range(1, n + 1):
            if not visited[i]:
                visited[i] = True
                max_cycle = max(max_cycle, adj[i].__len__() if adj[i] else 0)

        return str(max_cycle * 999 + 1)
    else:
        return str(n)
