    lines = input_str.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))

    # Monotonic stack solution
    # Stack stores (sum, count) for each group
    stack = []

    for num in a:
        current_sum = num
        current_count = 1

        # While we can merge to get lexicographically smaller sequence
        while stack and stack[-1][0] * current_count <= current_sum * stack[-1][1]:
            current_sum += stack.pop()[0]
            current_count += stack.pop()[1]

        stack.append((current_sum, current_count))

    # Build output
    result = []
    for s, c in stack:
        result.append(s / c)

    # Format output
    lines = []
    for val in result:
        lines.append(f"{val:.10f}")

    return '\n'.join(lines) + '\n'
