# Alternative correct implementation
def solution(s):
    data = s.strip().split('\n')
    if not data:
        return "NO"

    n, m = map(int, data[0].split())

    clauses = []
    for i in range(n):
        parts = list(map(int, data[i + 1].split()))
        clauses.append(parts[1:])

    # Check: each variable appears at most twice
    from collections import defaultdict
    cnt = defaultdict(int)
    for clause in clauses:
        for lit in clause:
            cnt[abs(lit)] += 1

    for c in cnt.values():
        if c > 2:
            return "NO"

    # If all clauses are empty or satisfiable trivially
    for clause in clauses:
        if not clause:
            return "YES" + "0" * m

    # Build implication graph and check 2-SAT
    num_nodes = 2 * m
    adj = [[] for _ in range(num_nodes)]
    rev = [[] for _ in range(num_nodes)]

    # For each clause with k literals, we could create exponential edges
    # But since each variable appears at most twice, we can use backtracking

    assignment = [0] * (m + 1)

    def check_satisfied():
        for clause in clauses:
            for lit in clause:
                var = abs(lit)
                is_neg = lit < 0
                val = assignment[var]
                if val == 1 and is_neg:
                    return True
                if val == 2 and not is_neg:
                    return True
        return False

    def backtrack(idx):
        if idx > m:
            for clause in clauses:
                sat = False
                for lit in clause:
                    val = check_literal(lit, assignment)
                    if val:
                        sat = True
                        break
                if not sat:
                    return False
            return True

        var = idx
        # Try setting to true
        assignment[var] = 1
        if backtrack(idx + 1):
            return True
        # Try setting to false
        assignment[var] = 2
        if backtrack(idx + 1):
            return True

        return False

    def check_literal(lit, assignment):
        var = abs(lit)
        is_neg = lit < 0
        val = assignment[var]
        if is_neg:
            return val == 2  # false assignment means literal is true
        else:
            return val == 1  # true assignment means literal is true

    # Try both assignments if no trivial solution
    result = backtrack(1)

    if result:
        # Build result string
        res = []
        for i in range(1, m + 1):
            res.append(str(1 if assignment[i] == 1 else 0))
        return "YES" + "\n" + "".join(res)
    return "NO"
