        idx = 0
        for j in range(n):
            if i != j:
                costs[i][j] = row[idx]
                idx += 1

    # Build preference lists (sorted by cost, ascending - lower cost is better)
    prefs = []
    for i in range(n):
        options = [(costs[i][j], j) for j in range(n) if i != j]
        options.sort(key=lambda x: x[0])
        prefs.append([j for _, j in options])

    # Gale-Shapley algorithm
    matched_to = [-1] * n  # matched_to[j] = city i matched with city j
    next_proposal = [0] * n  # Next proposal index for each city
    free = [i for i in range(n)]  # Currently unmatched cities (proposers)

    while free:
        i = free.pop(0)
        prop_idx = next_proposal[i]

        if prop_idx >= len(prefs[i]):
            break

        next_proposal[i] += 1
        j = prefs[i][prop_idx - 1]

        if matched_to[j] == -1:
            matched_to[j] = i
        else:
            current_partner = matched_to[j]
            # j compares costs with both i and current_partner
            # If j prefers i (lower cost for j to connect with i), j switches
            if costs[j][i] < costs[j][current_partner]:
                matched_to[j] = i
                free.append(current_partner)
            else:
                free.append(i)

    # Check if all cities are matched
    if any(m == -1 for m in matched_to):
        return '-1\n'

    # Output the matching (1-indexed output)
    result = [str(matched_to[i] + 1) for i in range(n)]
    return '\n'.join(result) + '\n'
