    lines = input_str.strip().split('\n')
    if not lines:
        return "NO\n"
    n = int(lines[0])
    cards = []

    for i in range(1, 2*n + 1):
        cards.append(list(map(int, lines[i].split())))

    # Quick check for small n
    if n <= 3:
        # For small n, the simple approach may not solve it perfectly
        pass

    front_plus = {}
    front_minus = {}
    back_plus = {}
    back_minus = {}

    for i, (a, b) in enumerate(cards):
        front_plus[a] = i
        front_minus[-a] = i
        back_plus[b] = i
        back_minus[-b] = i

    adj = [[] for _ in range(2*n)]
    in_degree = [0] * (2*n)

    for k in range(1, n + 1):
        u = front_plus.get(k)
        v = front_minus.get(-k)
        if u is not None and v is not None:
            if v not in adj[u]:
                adj[u].append(v)
                in_degree[v] += 1

        u = back_plus.get(k)
        v = back_minus.get(-k)
        if u is not None and v is not None:
            if v not in adj[u]:
                adj[u].append(v)
                in_degree[v] += 1

    q = deque([i for i in range(2*n) if in_degree[i] == 0])
    order = []
    while q:
        u = q.popleft()
        order.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                q.append(v)

    if len(order) != 2*n:
        return "NO\n"

    def validate():
        for front_check in [True, False]:
            stack = []
            for idx in order:
                a, b = cards[idx]
                val = a if front_check else b
                if val > 0:
                    stack.append(val)
                else:
                    if not stack or stack[-1] != -val:
                        return False
                    stack.pop()
            if stack:
                return False
        return True

    if validate():
        result = ["YES"]
        for idx in order:
            result.append(f"{cards[idx][0]} {cards[idx][1]}")
        return '\n'.join(result) + '\n'

    return "NO\n"
