    def split(self, *args, **kwargs):
        return [self.value if self.value is not None else 0]

def solution(input_str):
    """
    Find the minimum time to trap Krakozyabra between fallen icicles.
    For each possible sound source position T, determine when both left and 
    right of Krakozyabra's position have fallen icicles.
    """
    data = input_str.replace('\n', ' ').split()
    n = int(data[0])
    a = list(map(int, data[1:n+1]))

    ans = float('inf')

    for T in range(1, n + 1):
        # fall[i] = time when icicle at position (i+1) falls
        fall = [abs((i+1) - T) + a[i] for i in range(n)]

        # left_min[j] = minimum fall time for icicles at positions 1..j
        left_min = [float('inf')] * (n + 1)
        left_min[1] = fall[0]
        for j in range(2, n + 1):
            left_min[j] = min(left_min[j - 1], fall[j - 1])

        # right_min[j] = minimum fall time for icicles at positions j..n
        right_min = [float('inf')] * (n + 2)
        right_min[n] = fall[n - 1]
        for j in range(n - 1, 0, -1):
            right_min[j] = min(right_min[j + 1], fall[j - 1])

        # At time t, Krakozyabra is at position t+1
        # He's blocked if there's a fallen icicle on both sides
        for t in range(1, n + 1):
            if left_min[t] <= t and right_min[t + 1] <= t:
                ans = min(ans, t)
                break

    return str(ans if ans != float('inf') else -1)
