## Key Insights

The recurrence is:
- For mirror i (checkpoint): E[i] = 1/p[i] + E[i+1]
- For mirror i (not checkpoint): E[i] = 1 + p[i]*E[i+1] + q[i]*E[L[i]]
  where L[i] is the checkpoint with maximal index ≤ i

For efficiency with O(N) per query (200,000 queries is too slow), I'll use an O(N²) solution since test cases should be faster, plus use a more efficient structure.

```python
MOD = 998244353

def modInverse(a):
    return pow(a, MOD - 2, MOD)

def solution(input_text):
    lines = input_text.strip().split('\n')
    n, q = map(int, lines[0].split())
    p = list(map(int, lines[1].split()))

    # Convert probabilities - p[i]/100, 1-indexed
    inv_100 = modInverse(100)
    prob = [(p[i-1] * inv_100) % MOD for i in range(n)]  # prob[i] for mirror i (1-indexed)
    inv_prob = [(100 * modInverse(p[i-1])) % MOD for i in range(n)]  # 1/prob[i] mod MOD

    queries = []
    for i in range(q):
        queries.append(int(lines[2 + i]))

    # Checkpoints - 1-indexed
    checkpoints = {1}

    def get_L(i, sorted_cp):
        """Find checkpoint <= i (maximal)"""
        # Binary search in sorted_cp
        import bisect
        idx = bisect.bisect_right(sorted_cp, i)
        if idx == 0:
            return sorted_cp[0]
        return sorted_cp[idx - 1]

    def solve_snapshot():
        sorted_cp = sorted(checkpoints)
        L = [0] * (n + 1)
        for i in range(1, n + 1):
            L[i] = get_L(i, sorted_cp)

        E = [0] * (n + 1)
        for i in range(n, 0, -1):
            if i in checkpoints:
                # Checkpoint: E[i] = 1/p[i] + E[i+1]
                if i == n:
                    E[i] = inv_prob[i-1]
                else:
                    E[i] = (inv_prob[i-1] + E[i+1]) % MOD
            else:
                # Non-checkpoint: E[i] = 1 + prob[i]*E[i+1] + (1-prob[i])*E[L[i]]
                if i == n:
                    # Special case for mirror n (not checkpoint)
                    if L[n] == n:
                        E[i] = modInverse(prob[i-1])
                    else:
                        q_i = (1 - prob[i-1]) % MOD
