            if i > 0 and len(lines) - i > 2:  # More lines after grid
                end_idx = i
                break

            end_idx = i

        return n, m, swapLR, swapUD, grid

    def _get_next_pos(r, c, move, n, m, swapLR, swapUD, grid):
        """Get next position considering swaps, returns (nr, nc, valid)"""
        if move == 'U':
            dr, dc = -1, 0 if not swapLR else 1
            if swapUD:
                dr, dc = dr * -1, dc
        elif move == 'D':
            dr, dc = 1, 0 if not swapLR else 1
            if swapUD:
                dr, dc = dr * -1, dc
        elif move == 'L':
            dr, dc = 0, -1 if not swapLR else 1
            if swapUD:
                dr, dc = dr, dc * -1
        elif move == 'R':
            dr, dc = 0, 1 if not swapLR else -1
            if swapUD:
                dr, dc = dr, dc * -1

        nr, nc = r + dr, c + dc

        if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] != '*':
            return nr, nc, True

        r, c = nr, nc

    def solve_maze(n, m, swapLR, swapUD, grid):
        # Find start (0,0) and target (where grid[r][c] == 'F')
        start = (0, 0)
        target = None

