        # BFS
        queue = deque()
        queue.append(start)
        parent = {}
        parent[start] = (None, None)
        visited = set()
        visited.add(start)

        while queue:
            curr = queue.popleft()
            if curr == target:
                break

            r, c = curr
            for move in ['U', 'D', 'L', 'R']:
                nr, nc, valid = _get_next_pos(r, c, move, n, m, swapLR, swapUD, grid)
                if valid and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    parent[(nr, nc)] = (curr, move)
                    queue.append((nr, nc))

        # Reconstruct path
        if target in parent:
            path = []
            curr = target
            while curr != start:
                prev_r, prev_c, move = parent[curr]
                path.append(move)
                curr = (prev_r, prev_c)
            return '\n'.join(reversed(path))
        return ""

