        v, s, t = int(parts[0]), int(parts[1]), int(parts[2])
        queries.append((v, s, t))
        road_idx += 1

    # Tarjan's SCC
    visited = [False] * (n + 1)
    stack = []
    on_stack = [False] * (n + 1)
    ids = [-1] * (n + 1)
    low = [-1] * (n + 1)
    idx = 0
    scc_ids = [-1] * (n + 1)
    scc_count = 0

    def dfs_scc(u):
        nonlocal idx, scc_count
        stack.append(u)
        on_stack[u] = True
        visited[u] = True
        ids[u] = low[u] = idx
        idx += 1

        for v, l in adj[u]:
            if ids[v] == -1:
                dfs_scc(v)
                low[u] = min(low[u], low[v])
            elif on_stack[v]:
                low[u] = min(low[u], ids[v])

        if low[u] == ids[u]:
            while stack:
                node = stack.pop()
                on_stack[node] = False
                scc_ids[node] = scc_count
                if node != u:
                    break
            scc_count += 1

    for i in range(1, n + 1):
        if ids[i] == -1:
            dfs_scc(i)

    # Compute cycle GCD for each SCC
    scc_cycle_gcd = {}

    for scc in range(scc_count):
        nodes = [i for i in range(1, n + 1) if scc_ids[i] == scc]
        if len(nodes) <= 1:
            scc_cycle_gcd[scc] = 0
            continue

        # Small SCC, enumerate cycles
        all_cycles = []
        for start in nodes:
            if not adj[start]:
                continue
            stack = [(start, start)]
            while stack:
                u, path = stack.pop()
                for v, l in adj[u]:
                    if v == start and v != path[1]:
                        all_cycles.append(path[1])
                    elif scc_ids[v] == scc and v not in path[1]:
                        stack.append((v, path[1] + l))

        if all_cycles:
            g = all_cycles[0]
            for c in all_cycles[1:]:
                g = math.gcd(g, c)
            scc_cycle_gcd[scc] = g
        else:
            scc_cycle_gcd[scc] = 0

    results = []

    for v, s, t in queries:
        scc = scc_ids[v]
        gcd_val = scc_cycle_gcd[scc]

        if s == 0:
            results.append("YES")
        elif gcd_val == 0:
            # Check if v can reach itself
            queue = [v]
            visited = {v}
            found = False
            while queue:
                u = queue.pop(0)
                for neighbor, _ in adj[u]:
                    if neighbor == v:
                        found = True
                        break
                    if neighbor not in visited:
                        visited.add(neighbor)
                        queue.append(neighbor)
                if found:
                    break
            results.append("YES" if found else "NO")
        else:
            # Check divisibility
            req = (t - s) % t
            if req == 0:
                results.append("YES")
            elif req % gcd_val == 0:
                results.append("YES")
            else:
                results.append("NO")

    return '\n' + '\n'.join(results)
