import sys
import os

sys.setrecursionlimit(2000000)

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def solution(data):
    if not data or data.strip() == '':
        return ''

    x, y = map(int, data.split())

    def f(a, b):
        # Base case
        if b == 0:
            return 0

        g = gcd(a, b)

        # If y is exactly the gcd, we finish in 1 step
        if b % a == 0:
            return b // a

        # If g equals a (i.e., a divides b), answer is b // a
        if g == a:
            return b // a

        # If (b - g) is a multiple of a, the next gcd will be a
        if (b - g) > 0 and (b - g) % a == 0:
            return 1 + (b - g) // a

        # Otherwise subtract g once and continue (this happens fast)
        return 1 + f(a, b - g)

    return str(f(x, y))

if __name__ == "__main__":
    print(solution('3 5\n'))  # Expected: 3
    print(solution('6 3\n'))  # Expected: 1
    print(solution('1 100000000000\n'))  # Expected: 100000000000
