            continue

        # Compute g = gcd(u, v)
        g = gcd(u, v)

        if g == 1:
            u_p = u
            v_p = v
        else:
            u_p = u // g
            v_p = v // g

        # Compute factor sum for u_p
        sum_u = 0
        denom_u = 1
        temp = u_p

        for p in primes:
            count = 0
            while temp % (p ** (count + 1)) == 0:
                count += 1
            if count > 0:
                sum_u += count
                denom_u = (denom_u * factorialInverse(count)) % MOD

        # Compute factorial of sum_u
        fact_u = factorial(sum_u)
        ways_u = (fact_u * denom_u) % MOD

        # Compute factor sum for v_p
